def kth_largest_distinct(lst, k):
    if k < 1:
        return None
    distinct = set(lst)
    if k > len(distinct):
        return None
    return heapq.nlargest(k, distinct)[-1]

def sort_by_frequency_desc_then_first_occurrence(nums):
    seen_order = []
    freq = {}
    for x in nums:
        if x not in freq:
            seen_order.append(x)
        freq[x] = freq.get(x, 0) + 1
    return sorted(seen_order, key=lambda v: -freq[v])

